export const MainBakset = ({ navigation, route }) => {

    const CityLoadPhone =  useSelector(state => state.post.cityLoadPhone);
    const AuthUserStatus =  useSelector(state => state.post.AuthUserStatus);
    const statusDelivery = useSelector(state=>state.post.typeDeliverySystem);

    const DeliveryAdresSystem = useSelector(state => state.post.adressSelect);

    const AffiliateAdresSystem = useSelector(state => state.post.affiliateSelect);
    const TypeDeliverySystem = useSelector(state => state.post.typeDeliverySystem);

    let CheckNulls = null;
    let CheckedOffCategorys = [];

    let NoneCategoryStop = [];
    let TextNoneDelivered = "Нет доставки на Ваш адрес";

    if(TypeDeliverySystem === true){
        CheckNulls = DeliveryAdresSystem;
        CheckedOffCategorys = DeliveryAdresSystem;
        NoneCategoryStop = DeliveryAdresSystem?.OffCategoryData?.OffCategory;
        TextNoneDelivered = "Нет доставки на Ваш адрес"
    }else{
        CheckNulls = AffiliateAdresSystem;
        CheckedOffCategorys = AffiliateAdresSystem;
        NoneCategoryStop = AffiliateAdresSystem?.JsonNoneCheck?.category_none;
        TextNoneDelivered = "Не готовят на выбранной точке"
    }

    if(typeof (NoneCategoryStop) === "object"){
        NoneCategoryStop = Object.keys(NoneCategoryStop);
    }

    if(NoneCategoryStop?.length <0 || NoneCategoryStop === undefined || NoneCategoryStop === null){
        NoneCategoryStop = [];
    }


    if (CityLoadPhone || (!AuthUserStatus)) {
        // navigation.navigate('Authorization');
        return (
            <View style={styles.center}>
                <Text style={{fontSize:14,textAlign:"center",marginBottom:20}}>Чтобы свершить заказ, Вам нужно подтвердить номер телефона, а для этого необходимо войти в аккаунт или создать его.</Text>
                <Pressable
                    style={styles.buttonCity}
                    color={THEME.MAIN_COLOR}
                    onPress={() => {
                        window.location.hash = 'Authorization';
                        navigation.navigate('Authorization');
                    }}
                >
                    <Text style={{color:THEME.MAIN_COLOR,fontFamily:"open-bold, segoe ui, Arial", fontWeight:700,marginVertical:20}}>Авторизоваться</Text>
                </Pressable>
            </View>
        )
    } else {

        if(CheckNulls === null){
            return (
                <View style={styles.center}>
                    <Text style={{fontSize:14,textAlign:"center",marginBottom:20}}>Не выбран адрес доставки или самовывоза</Text>

                    <Pressable
                        style={styles.buttonCity}
                        color={THEME.MAIN_COLOR}
                        onPress={() => {
                            // navigation.navigate('Main');
                            if(TypeDeliverySystem == true) {
                                window.location.hash = 'AdressList';
                                navigation.navigate('AdressList', {
                                    productId: 1,
                                    title: "Доставка",
                                    booked: false,
                                    returnBasket: true,
                                    productData: [{id: 1, title: "Доставка", booked: false}]
                                });
                            }else{
                                window.location.hash = 'AffiliateList';
                                navigation.navigate('AffiliateList', {
                                    productId: 1,
                                    title: "Самовывоз",
                                    booked: false,
                                    returnBasket: true,
                                    productData:[{id:1,title:"Самовывоз",booked:false}]
                                });
                            }
                        }}
                    >
                        <Text style={{color:THEME.MAIN_COLOR,fontFamily:"open-bold, segoe ui, Arial", fontWeight:700,marginVertical:20}}>Выберите адрес</Text>
                    </Pressable>
                </View>
            )
        }else {
            return (
                <GoodPages navigation={navigation} route={route}/>
            )
        }
    }

}

export const GoodPages = ({ navigation, route }) => {

    const dispatch = useDispatch();
    const calculatedBasketSum = GetAllPriceBasket();

    const basket = useSelector(state => state.post.basket);
    const allProducts = useSelector(state => state.post.allProducts);
    const liveBasketSum = Number(calculatedBasketSum) || 0;
    const CityIdActive = useSelector(state=>state.post.cityData.cityId);
    const BasketActiveStatus = useSelector(state=>state.post.AuthUserData.BasketServerSettings[CityIdActive].active_app_mobile_v2);
    const modalVisiblePreloader = useSelector(state=>state.post.modalStateStatus.MODAL_ORDER_PRELOADER);

    const modalStateStatus = useSelector(state=>state.post.modalStateStatus);
    const cityId = useSelector(state => state.post.cityData.cityId);
    const conflictAlertKeyRef = useRef('');
    const suppressConflictPopupOnceRef = useRef(false);
    const [conflictModalVisible, setConflictModalVisible] = useState(false);
    const [conflictItems, setConflictItems] = useState([]);
    const [conflictPreorderVisible, setConflictPreorderVisible] = useState(false);
    const [conflictProductForPreorder, setConflictProductForPreorder] = useState(null);
    const [conflictProductsForPreorder, setConflictProductsForPreorder] = useState([]);

    useEffect(() => {
        const unsubBlur = navigation.addListener('blur', () => {
            const keys = [
                'MODAL_ORDER',
                'MODAL_PROMOKODE',
                'MODAL_PROMOKODE_SUCCESS',
                'MODAL_PROMOKODE_ERROR',
                'MODAL_GIFTS',
                'MODAL_DATE_DELIVERY',
                'MODAL_TIME_DELIVERY',
                'MODAL_ORDER_PRELOADER',
                'MODAL_MODIFY_LIST',
            ];
            keys.forEach((key) => {
                if (modalStateStatus?.[key]) {
                    dispatch(setModalStatus(key, false));
                }
            });

            if (conflictModalVisible) {
                setConflictModalVisible(false);
            }
            if (conflictPreorderVisible) {
                setConflictPreorderVisible(false);
            }
        });
        return () => {
            unsubBlur && unsubBlur();
        };
    }, [navigation, modalStateStatus, dispatch, conflictModalVisible, conflictPreorderVisible]);

    const isFocused = useIsFocused();
    const preorderData = useSelector(state => state.post.preorderData);
    const invalidMap = useMemo(() => {
        const map = {};
        if (!Array.isArray(basket) || basket.length === 0) {
            return map;
        }
        basket.forEach((item) => {
            const productId = item?.id;
            const types = Array.isArray(item?.type) ? item.type : [];
            let invalid = false;
            let title = 'Товар';
            types.forEach((t) => {
                const categoryId = t?.categoryId;
                const product = extractProductFromAllProducts(allProducts, categoryId, productId);
                if (product?.title) {
                    title = product.title;
                }
                if (!product) {
                    return;
                }
                if (!isAllowedByMenuStopForSelection(product, preorderData)) {
                    invalid = true;
                }
            });
            if (invalid) {
                map[productId] = title;
            }
        });
        return map;
    }, [basket, allProducts, preorderData]);

    useEffect(() => {
        if (!isFocused) return;
        const invalidIds = Object.keys(invalidMap);
        if (!Array.isArray(basket) || basket.length === 0 || invalidIds.length === 0) {
            conflictAlertKeyRef.current = '';
            suppressConflictPopupOnceRef.current = false;
            setConflictModalVisible(false);
            setConflictItems([]);
            return;
        }

        const alertKey = invalidIds.sort().join(',');
        if (suppressConflictPopupOnceRef.current) {
            suppressConflictPopupOnceRef.current = false;
            conflictAlertKeyRef.current = alertKey;
            return;
        }
        if (conflictAlertKeyRef.current === alertKey) {
            return;
        }
        conflictAlertKeyRef.current = alertKey;
        setConflictItems(invalidIds.map((id) => ({ id: id * 1, title: invalidMap[id] })));
        setConflictModalVisible(true);
    }, [basket, invalidMap, isFocused]);

    const resolveProductForConflict = useCallback((productId) => {
        if (!Array.isArray(basket)) {
            return null;
        }
        const basketRow = basket.find((b) => (b?.id * 1) === (productId * 1));
        if (!basketRow) {
            return null;
        }
        const types = Array.isArray(basketRow.type) ? basketRow.type : [];
        for (let i = 0; i < types.length; i++) {
            const categoryId = types[i]?.categoryId;
            const productList = allProducts?.[categoryId]?.ProductList?.[productId];
            if (Array.isArray(productList) && productList[0]) {
                return productList[0];
            }
        }
        return null;
    }, [basket, allProducts]);

    const resolveProductsForConflicts = useCallback((items) => {
        if (!Array.isArray(items)) { return []; }
        const result = [];
        const seen = {};
        items.forEach((row) => {
            const p = resolveProductForConflict(row?.id);
            if (!p) { return; }
            const pid = (p.id != null) ? (p.id * 1) : ((row?.id || 0) * 1);
            if (seen[pid]) { return; }
            seen[pid] = true;
            result.push(p);
        });
        return result;
    }, [resolveProductForConflict]);

    const PromokodeDate = useSelector(state=>state.post.promokodeData);
    const StatusPromoLink = useSelector(state=>state.post.StatusPromoLink);
    const idUserSystem = useSelector(state => state.post.AuthUserData.id);

    const HashProodata = useSelector(state => state.post.HashProodata);




    const activePromoURL = async (idCity,idUser)=>{

        if(HashProodata !== null) {
            if (PromokodeDate === null) {
                if (!StatusPromoLink) {
                    await dispatch(setModalStatus('MODAL_PROMOKODE',true));
                    const ReultServer = await ServerDB.getPromokodeActive(idCity, idUser, HashProodata);

                    if (ReultServer.error === null) {
                        await dispatch(setPromokodeErrorUpdate(false, null));
                        await dispatch(setPromokodeUpdate(ReultServer.result, true));

                    } else {
                        await dispatch(setPromokodeErrorUpdate(true, ReultServer.errorInfo));
                        await dispatch(setPromokodeUpdate(null, false));
                    }

                    console.log('Активирвоать промокод! ', idCity, idUser, HashProodata, ReultServer, PromokodeDate);
                }
            }
        }
    };


    useEffect(()=>{
        activePromoURL(CityIdActive,idUserSystem);
    });





    if (BasketActiveStatus*1 === 0) {
        return (
            <View style={styles.center}>
                <AntDesign name="closecircleo" size={50} color={THEME.MAIN_COLOR} />
                <Text style={styles.TextInfo}>Корзина отключена</Text>
                <Text style={styles.TextInfoMini}>Приносим извинения, корзина временно не доступна!</Text>
            </View>
        )
    }

    if (basket.length<=0) {
        return (
            <View style={styles.center}>
                <AntDesign name="closecircleo" size={50} color={THEME.MAIN_COLOR} />
                <Text style={styles.TextInfo}>Корзина пуста</Text>
                <Text style={styles.TextInfoMini}>Для того чтобы продолжить, положите хотя бы один товар в корзину</Text>
            </View>
        )
    }

    const ModalPreloader = ()=>{
        return (
            <Modal
                animationType="fade"
                transparent={true}
                visible={modalVisiblePreloader}
                onShow={()=> {
                    // Alert.alert("Модальное окно было открыто");
                }}
                onRequestClose={() => {
                    // Alert.alert("Модальное окно было закрыто");
                    setModalVisible(!modalVisiblePreloader);
                }}
            >
                <View style={styles.preloaderModal}>
                    <Text style={{fontSize:16,paddingVertical:10}}>Отправляем заказ</Text>
                    <ActivityIndicator color={THEME.MAIN_COLOR} size={26}/>
                </View>
            </Modal>
        );
    }

    return (
            <View style={styles.center}>
                <View style={styles.safeArea} key={"MainScr"}>
            {/*<ScaleGift navigation={navigation}/>*/}
            <ListProductBasket navigation={navigation} route={route} liveBasketSum={liveBasketSum}/>
            <OrderModal navigation={navigation} route={route} liveBasketSum={liveBasketSum}/>
            <PromokodeModal />
            <ModalPreloader />
            {isFocused && conflictModalVisible && <Modal
                animationType="fade"
                transparent={true}
                visible={true}
                onRequestClose={() => setConflictModalVisible(false)}
            >
                <View style={styles.conflictOverlay}>
                    <View style={styles.conflictCard}>
                        <Text style={styles.conflictTitle}>Товары недоступны</Text>
                        <Text style={styles.conflictText}>Для выбранной даты и времени часть товаров недоступна.</Text>
                        {conflictItems.slice(0, 4).map((row) => (
                            <Text key={"conflict_" + row.id} style={styles.conflictItem}>• {row.title}</Text>
                        ))}
                        <View style={styles.conflictActions}>
                            <Pressable
                                style={[styles.conflictBtn, styles.conflictBtnGhost]}
                                onPress={() => {
                                    setConflictModalVisible(false);
                                    const firstConflict = conflictItems[0];
                                    const product = firstConflict ? resolveProductForConflict(firstConflict.id) : null;
                                    if (product) {
                                        setConflictProductForPreorder(product);
                                        setConflictProductsForPreorder(resolveProductsForConflicts(basket));
                                        setConflictPreorderVisible(true);
                                    }
                                }}
                            >
                                <Text style={styles.conflictBtnGhostText}>Выбрать время</Text>
                            </Pressable>
                            <Pressable
                                style={[styles.conflictBtn, styles.conflictBtnDanger]}
                                onPress={() => {
                                    const idSet = {};
                                    conflictItems.forEach((row) => { idSet[row.id] = true; });
                                    const nextBasket = basket.filter((row) => !idSet[row.id * 1]);
                                    dispatch(addProductBasket(nextBasket));
                                    conflictAlertKeyRef.current = '';
                                    setConflictModalVisible(false);
                                    setConflictProductsForPreorder([]);
                                }}
                            >
                                <Text style={styles.conflictBtnDangerText}>Удалить товары</Text>
                            </Pressable>
                        </View>
                    </View>
                </View>
            </Modal>}
            {isFocused && conflictPreorderVisible && <PreorderPickerModal
                visible={isFocused && conflictPreorderVisible}
                product={conflictProductForPreorder}
                cityId={cityId}
                onClose={() => {
                    setConflictPreorderVisible(false);
                    setConflictProductForPreorder(null);
                    setConflictProductsForPreorder([]);
                    if (Object.keys(invalidMap).length > 0) {
                        setConflictModalVisible(true);
                    }
                }}
                onConfirm={(selection) => {
                    suppressConflictPopupOnceRef.current = true;
                    dispatch(setPreorderData(selection));
                    setConflictPreorderVisible(false);
                    setConflictProductForPreorder(null);
                    setConflictProductsForPreorder([]);
                    conflictAlertKeyRef.current = '';
                }}
                extraProducts={conflictProductsForPreorder}
            />}
                </View>
            </View>
    );

};

