import {useEffect, useState} from 'react';
import {useSelector} from 'react-redux';

// Проверяем сегодняшнюю смену и ночную смену предыдущего дня.
export const isPickupOpenAt = (point, date = new Date()) => {
    if (!point?.worktime?.days || !Number.isFinite(date.getTime())) return false;
    for (const offset of [-1, 0]) {
        const day = new Date(date.getFullYear(), date.getMonth(), date.getDate() + offset);
        const schedule = point.worktime.days[day.getDay()];
        if (!schedule) continue;
        const values = [schedule.hoursStart, schedule.minuteStart, schedule.hoursStop, schedule.minuteStop];
        if (values.some(value => value == null || value === '' || !Number.isFinite(Number(value)))) continue;
        const [sh, sm, eh, em] = values.map(Number);
        if (sh < 0 || sh > 23 || eh < 0 || eh > 24 || sm < 0 || sm > 59 || em < 0 || em > 59) continue;
        const start = new Date(day.getFullYear(), day.getMonth(), day.getDate(), sh, sm);
        const end = new Date(day.getFullYear(), day.getMonth(), day.getDate(), eh, em);
        if (end < start) end.setDate(end.getDate() + 1);
        if (end > start && date >= start && date < end) return true;
    }
    return false;
};

export const isPickupSlotOpen = (point, day, time) => {
    const d = String(day).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    const t = String(time).match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
    if (!d || !t) return false;
    return isPickupOpenAt(point, new Date(Number(d[1]), Number(d[2])-1, Number(d[3]), Number(t[1]), Number(t[2])));
};

export const usePickupAvailability = pointOverride => {
    const selected = useSelector(state => state.post.affiliateSelect);
    const delivery = useSelector(state => state.post.typeDeliverySystem);
    const [now, setNow] = useState(() => Date.now());
    useEffect(() => {
        const timer = setInterval(() => setNow(Date.now()), 15000);
        return () => clearInterval(timer);
    }, []);
    const point = pointOverride === undefined ? selected : pointOverride;
    return {point, isPickup: delivery === false, openNow: isPickupOpenAt(point, new Date(now))};
};
