export const getMenuStopAvailability = (product) => {
  if (!product || typeof product !== "object") {
    return null;
  }
  const src = product.menu_stop_availability || null;
  if (!src || typeof src !== "object") {
    return null;
  }
  return src;
};

const MENU_STOP_UI_DEFAULTS = {
  badge_can_order: "Можно заказать:",
  badge_preorder_only: "Только по предзаказу",
  badge_unavailable_now: "Сейчас недоступно",
  badge_bg_color: "#fff3db",
  badge_text_color: "#c77918",
  badge_can_order_bg_color: "#fff3db",
  badge_can_order_text_color: "#c77918",
  badge_preorder_bg_color: "#fff3db",
  badge_preorder_text_color: "#c77918",
  badge_unavailable_bg_color: "#fff3db",
  badge_unavailable_text_color: "#c77918",
  badge_icon_size: "14",
  badge_text_size: "12",
  badge_time_size: "11",
};

const parseTimeToMin = (val) => {
  if (!val || typeof val !== "string" || val.indexOf(":") < 0) {
    return null;
  }
  const p = val.split(":");
  const h = parseInt(p[0], 10);
  const m = parseInt(p[1], 10);
  if (isNaN(h) || isNaN(m)) {
    return null;
  }
  return h * 60 + m;
};

const formatDateRuLong = (dateStr) => {
  if (!dateStr || typeof dateStr !== "string" || dateStr.indexOf("-") < 0) {
    return dateStr || "";
  }
  const p = dateStr.split("-");
  if (p.length !== 3) {
    return dateStr;
  }
  const months = {
    "01": "января",
    "02": "февраля",
    "03": "марта",
    "04": "апреля",
    "05": "мая",
    "06": "июня",
    "07": "июля",
    "08": "августа",
    "09": "сентября",
    "10": "октября",
    "11": "ноября",
    "12": "декабря",
  };
  const dd = String(parseInt(p[2], 10));
  const mm = p[1];
  return months[mm] ? `${dd} ${months[mm]}` : `${p[2]}.${p[1]}`;
};

const buildPreorderHint = (preorderDates, meta = {}) => {
  if (!Array.isArray(preorderDates) || !preorderDates.length) {
    return "";
  }
  let firstDate = "";
  let lastDate = "";
  const intervalMap = {};

  preorderDates.forEach((row) => {
    const dateIso = row?.date || "";
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateIso)) {
      return;
    }
    if (!firstDate || dateIso < firstDate) {
      firstDate = dateIso;
    }
    if (!lastDate || dateIso > lastDate) {
      lastDate = dateIso;
    }
    const windows = Array.isArray(row?.windows) ? row.windows : [];
    windows.forEach((w) => {
      if (typeof w !== "string" || w.indexOf("-") < 0) {
        return;
      }
      const parts = w.split("-");
      const start = String(parts[0] || "").trim();
      const end = String(parts[1] || "").trim();
      if (!/^\d{2}:\d{2}$/.test(start) || !/^\d{2}:\d{2}$/.test(end)) {
        return;
      }
      if (start >= end) {
        return;
      }
      intervalMap[`${start}-${end}`] = true;
    });
  });

  if (!firstDate) {
    return "";
  }

  const openEnded = meta.date_mode === 'open_ended_daily' && /^\d{4}-\d{2}-\d{2}$/.test(meta.date_from || '');
  let dateText = openEnded ? (meta.show_date_from ? 'с ' + formatDateRuLong(meta.date_from) : 'ежедневно') : formatDateRuLong(firstDate);
  if (!openEnded && lastDate && lastDate !== firstDate) {
    dateText += ` — ${formatDateRuLong(lastDate)}`;
  }

  const intervals = Object.keys(intervalMap).sort();
  if (intervals.length) {
    return `${dateText}; ${intervals.join(", ")}`;
  }
  return dateText;
};

const inWindow = (timeValue, range) => {
  if (!timeValue || !range || range.indexOf("-") < 0) {
    return false;
  }
  const t = parseTimeToMin(timeValue);
  if (t === null) {
    return false;
  }
  const p = range.split("-");
  const start = parseTimeToMin((p[0] || "").trim());
  const end = parseTimeToMin((p[1] || "").trim());
  if (start === null || end === null) {
    return false;
  }
  return t >= start && t <= end;
};

// Новый API явно отличает отсутствие ограничений от пустого списка разрешённых дат.
export const hasPreorderRestrictions = a => !!a && (
  typeof a.preorder_has_restrictions === 'boolean' ? a.preorder_has_restrictions :
  (a.preorder_available === false || (a.preorder_next_dates || []).length > 0 || !!a.now_has_restrictions)
);

export const isAllowedByMenuStopForSelection = (product, preorderData) => {
  const a = getMenuStopAvailability(product);
  if (!a) {
    return true;
  }

  const dateDelivery = preorderData?.dateDelivery || 0;
  const timeDelivery = preorderData?.timeDelivery || 0;

  // "Как можно скорее" = текущий режим
  if (!dateDelivery || dateDelivery === 0) {
    return !!a.available_now;
  }

  if (a.preorder_available === false) return false;
  if (!hasPreorderRestrictions(a)) return true;
  const offers = Array.isArray(a.preorder_next_dates) ? a.preorder_next_dates : [];
  const dayOffer = offers.find((d) => d && d.date === dateDelivery);
  if (!dayOffer) {
    return false;
  }

  // Дата выбрана, время еще нет — достаточно, что на дату есть окна
  const windows = Array.isArray(dayOffer.windows) ? dayOffer.windows : [];
  if (!timeDelivery || timeDelivery === 0) {
    return windows.length > 0;
  }

  return windows.some((w) => inWindow(String(timeDelivery), String(w)));
};

export const isHardBlockedByMenuStop = (product) => {
  const a = getMenuStopAvailability(product);
  if (!a) {
    return false;
  }
  const preorderAvailable = !!a.preorder_available;
  const nowAvailable = !!a.available_now;
  return !nowAvailable && !preorderAvailable;
};

export const getMenuStopBadgeData = (product) => {
  const a = getMenuStopAvailability(product);
  if (!a) {
    return null;
  }

  const hasRestrictions = !!a.now_has_restrictions;
  if (!hasRestrictions) {
    return null;
  }

  const uiTexts = {
    ...MENU_STOP_UI_DEFAULTS,
    ...(a.ui_texts && typeof a.ui_texts === "object" ? a.ui_texts : {}),
  };
  const style = {
    can_order_bg_color: uiTexts.badge_can_order_bg_color || uiTexts.badge_bg_color,
    can_order_text_color: uiTexts.badge_can_order_text_color || uiTexts.badge_text_color,
    preorder_bg_color: uiTexts.badge_preorder_bg_color || uiTexts.badge_bg_color,
    preorder_text_color: uiTexts.badge_preorder_text_color || uiTexts.badge_text_color,
    unavailable_bg_color: uiTexts.badge_unavailable_bg_color || uiTexts.badge_bg_color,
    unavailable_text_color: uiTexts.badge_unavailable_text_color || uiTexts.badge_text_color,
    icon_size: parseInt(uiTexts.badge_icon_size, 10) || 14,
    text_size: parseInt(uiTexts.badge_text_size, 10) || 12,
    time_size: parseInt(uiTexts.badge_time_size, 10) || 11,
  };
  const defaultBg = String(MENU_STOP_UI_DEFAULTS.badge_bg_color || "").toLowerCase();
  const defaultText = String(MENU_STOP_UI_DEFAULTS.badge_text_color || "").toLowerCase();
  const bg = String(uiTexts.badge_bg_color || "").toLowerCase();
  const text = String(uiTexts.badge_text_color || "").toLowerCase();
  const hasTypedCustomColors =
      String(style.can_order_bg_color || "").toLowerCase() !== bg ||
      String(style.can_order_text_color || "").toLowerCase() !== text ||
      String(style.preorder_bg_color || "").toLowerCase() !== bg ||
      String(style.preorder_text_color || "").toLowerCase() !== text ||
      String(style.unavailable_bg_color || "").toLowerCase() !== bg ||
      String(style.unavailable_text_color || "").toLowerCase() !== text;
  style.use_status_fallback_colors = !hasTypedCustomColors && bg === defaultBg && text === defaultText;

  const nowWindows = Array.isArray(a.now_allowed_windows) ? a.now_allowed_windows : [];
  const preorderDates = Array.isArray(a.preorder_next_dates) ? a.preorder_next_dates : [];
  const rawBadgeText = typeof product?.menu_stop_badge_text === "string" ? product.menu_stop_badge_text.trim() : "";

  if (rawBadgeText) {
    const parts = rawBadgeText.split("\n");
    const title = String(parts[0] || "").trim();
    const hint = String(parts.slice(1).join(" ").trim() || "");
    let type = "can_order";
    const lower = title.toLowerCase();
    if (lower.indexOf("недоступ") !== -1) {
      type = "unavailable";
    } else if (title.indexOf("Только по предзаказу") === 0) {
      type = "preorder";
    } else if (title.indexOf("Можно заказать") === 0) {
      type = "can_order";
    }
    return {
      type,
      title,
      hint,
      style,
    };
  }

  if (!a.available_now) {
    const firstDate = preorderDates.map(row => row?.date).filter(Boolean).sort()[0];
    if (a.preorder_available && firstDate && a.city_now_date && firstDate > a.city_now_date) {
      return {type:'preorder', title:uiTexts.badge_preorder_only, hint:buildPreorderHint(preorderDates, a.preorder_hint), style};
    }
    if (nowWindows.length > 0) {
      return {
        type: "unavailable",
        title: uiTexts.badge_unavailable_now || MENU_STOP_UI_DEFAULTS.badge_unavailable_now,
        hint: nowWindows.join(", "),
        style,
      };
    }
    if (!!a.preorder_available) {
      const hint = buildPreorderHint(preorderDates, a.preorder_hint);
      return {
        type: "preorder",
        title: uiTexts.badge_preorder_only || MENU_STOP_UI_DEFAULTS.badge_preorder_only,
        hint,
        style,
      };
    }
    return {
      type: "unavailable",
      title: uiTexts.badge_unavailable_now || MENU_STOP_UI_DEFAULTS.badge_unavailable_now,
      hint: "",
      style,
    };
  }

  if (nowWindows.length > 0) {
    return {
      type: "can_order",
      title: uiTexts.badge_can_order || MENU_STOP_UI_DEFAULTS.badge_can_order,
      hint: nowWindows.join(", "),
      style,
    };
  }

  return null;
};

export const isTimeInAnyWindow = (timeValue, windows) => {
  if (!timeValue || !Array.isArray(windows) || !windows.length) {
    return false;
  }
  return windows.some((w) => inWindow(String(timeValue), String(w)));
};

export const extractProductFromAllProducts = (allProducts, categoryId, productId) => {
  const list = allProducts?.[categoryId]?.ProductList?.[productId];
  if (Array.isArray(list) && list.length) {
    return list[0];
  }
  return null;
};

export const getAvailableDatesForBasket = (basket, allProducts) => {
  let mapByDate = null;
  let hasRestricted = false;

  (basket || []).forEach((item) => {
    const productId = item?.id;
    (item?.type || []).forEach((t) => {
      const categoryId = t?.categoryId;
      const product = extractProductFromAllProducts(allProducts, categoryId, productId);
      const a = getMenuStopAvailability(product);
      if (!a) {
        return;
      }
      const nowWindows = Array.isArray(a.now_allowed_windows) ? a.now_allowed_windows : [];
      const offers = Array.isArray(a.preorder_next_dates) ? a.preorder_next_dates : [];
      const isRestricted = hasPreorderRestrictions(a);
      if (!isRestricted) {
        return;
      }
      hasRestricted = true;
      const dateSet = {};
      offers.forEach((o) => {
        if (o?.date) {
          dateSet[o.date] = true;
        }
      });
      if (mapByDate === null) {
        mapByDate = dateSet;
      } else {
        Object.keys(mapByDate).forEach((d) => {
          if (!dateSet[d]) {
            delete mapByDate[d];
          }
        });
      }
    });
  });

  if (!hasRestricted) {
    return null;
  }
  return Object.keys(mapByDate || {});
};

export const filterTimeSlotsForBasketAndDate = (timeKeys, basket, allProducts, dateValue) => {
  const base = Array.isArray(timeKeys) ? timeKeys.slice() : [];
  if (!dateValue || dateValue === 0) {
    return base;
  }
  let result = base.slice();
  let hasRestricted = false;

  (basket || []).forEach((item) => {
    const productId = item?.id;
    (item?.type || []).forEach((t) => {
      const categoryId = t?.categoryId;
      const product = extractProductFromAllProducts(allProducts, categoryId, productId);
      const a = getMenuStopAvailability(product);
      if (!a) {
        return;
      }
      const nowWindows = Array.isArray(a.now_allowed_windows) ? a.now_allowed_windows : [];
      const offers = Array.isArray(a.preorder_next_dates) ? a.preorder_next_dates : [];
      const isRestricted = hasPreorderRestrictions(a);
      if (!isRestricted) {
        return;
      }
      hasRestricted = true;
      const dayOffer = offers.find((d) => d && d.date === dateValue);
      if (!dayOffer) {
        result = [];
        return;
      }
      const windows = Array.isArray(dayOffer.windows) ? dayOffer.windows : [];
      result = result.filter((time) => isTimeInAnyWindow(time, windows));
    });
  });

  if (!hasRestricted) {
    return base;
  }
  return result;
};
