import React, {forwardRef, useEffect, useState} from 'react';
import {View} from 'react-native';
import * as Font from 'expo-font';
import * as Icons from '@expo/vector-icons';
import {subscribeIconFonts} from '../utils/iconFonts';

// Обновляется только иконка, без перемонтирования экрана и сброса прокрутки.
function withLoadedFont(Icon) {
    const isReady = () => Object.keys(Icon.font).every(name => Font.isLoaded(name));
    const Wrapped = forwardRef((props, ref) => {
        const [ready, setReady] = useState(isReady);
        useEffect(() => {
            const update = () => setReady(isReady());
            const unsubscribe = subscribeIconFonts(update);
            update();
            return unsubscribe;
        }, []);
        if (!ready) return <View accessible={false} style={[{width:props.size || 24, height:props.size || 24}, props.style]} />;
        return <Icon {...props} ref={ref} />;
    });
    Wrapped.font = Icon.font;
    return Wrapped;
}

export const AntDesign = withLoadedFont(Icons.AntDesign);
export const Entypo = withLoadedFont(Icons.Entypo);
export const Feather = withLoadedFont(Icons.Feather);
export const FontAwesome = withLoadedFont(Icons.FontAwesome);
export const FontAwesome5 = withLoadedFont(Icons.FontAwesome5);
export const Ionicons = withLoadedFont(Icons.Ionicons);
export const MaterialCommunityIcons = withLoadedFont(Icons.MaterialCommunityIcons);
export const MaterialIcons = withLoadedFont(Icons.MaterialIcons);
