import React, {useEffect} from 'react';
import {ActivityIndicator, ScrollView, Text, TouchableOpacity, View} from 'react-native';
import {useDispatch, useSelector} from 'react-redux';
import {loadCity} from '../store/actions/post';
import {CityModal} from './CityModal';
import {THEME} from '../theme';

// Каталог и авторизация с городом запускаются только после проверки серверного списка.
export default function CityBootstrap({children}) {
    const dispatch = useDispatch();
    const status = useSelector(state => state.post.cityDirectoryStatus);
    const cities = useSelector(state => state.post.cityList);
    const city = useSelector(state => state.post.cityData);
    useEffect(() => {
        dispatch(loadCity());
        if (typeof window === 'undefined') return;
        const onCity = event => dispatch(loadCity(event.detail));
        window.addEventListener('native-city-frame', onCity);
        return () => window.removeEventListener('native-city-frame', onCity);
    }, [dispatch]);

    if (status === 'ready' && cities[city?.cityId]) return children;
    const loading = status === 'idle' || status === 'loading';
    const failed = status === 'error';
    const ids = Object.keys(cities);
    if (status === 'ready' && ids.length) {
        return <CityModal requiredSelection />;
    }
    return <View style={{flex: 1, backgroundColor: '#fff', justifyContent: 'center', padding: 24}}>
        {loading ? <ActivityIndicator color={THEME.MAIN_COLOR}/> : <ScrollView contentContainerStyle={{flexGrow: 1, justifyContent: 'center', maxWidth: 440, width: '100%', alignSelf: 'center'}}>
            <Text style={{fontSize: 22, fontWeight: '600', color: '#222', marginBottom: 12}}>
                {failed ? 'Не удалось загрузить города' : 'Нет доступных городов'}
            </Text>
            <Text style={{fontSize: 15, color: '#777', marginBottom: 16}}>
                {failed ? 'Проверьте соединение и попробуйте ещё раз. Ваш сохранённый выбор не удалён.' : 'Попробуйте обновить список позже.'}
            </Text>
            {(failed || !ids.length) && <TouchableOpacity onPress={() => dispatch(loadCity(null, true))} style={{paddingVertical: 16}}>
                <Text style={{fontSize: 17, color: THEME.MAIN_COLOR}}>Повторить загрузку</Text>
            </TouchableOpacity>}
        </ScrollView>}
    </View>;
}
