import React from 'react';
import {StyleSheet, Text, View} from 'react-native';
import Svg, {Circle, Rect, Path} from 'react-native-svg';

const ICON_BY_TYPE = {
    unavailable: 'closecircleo',
    preorder: 'calendar',
    can_order: 'clockcircleo'
};

export const MenuStopBadge = ({badge, compact = false, fullWidth = false}) => {
    if (!badge) {
        return null;
    }
    const type = badge.type || 'can_order';
    const styleCfg = badge.style || {};
    const bgColor = type === 'unavailable'
        ? (styleCfg.unavailable_bg_color || '#fff5f5')
        : (type === 'preorder' ? (styleCfg.preorder_bg_color || '#fff8ee') : (styleCfg.can_order_bg_color || '#effaf3'));
    const textColor = type === 'unavailable'
        ? (styleCfg.unavailable_text_color || '#b42318')
        : (type === 'preorder' ? (styleCfg.preorder_text_color || '#92400e') : (styleCfg.can_order_text_color || '#166534'));
    const iconSize = Math.max(8, Math.min(28, parseInt(styleCfg.icon_size, 10) || (compact ? 11 : 13)));
    const titleSize = Math.max(8, Math.min(28, parseInt(styleCfg.text_size, 10) || (compact ? 11 : 12)));
    const hintSize = Math.max(8, Math.min(28, parseInt(styleCfg.time_size, 10) || (compact ? 10 : 11)));
    const iconName = ICON_BY_TYPE[type] || ICON_BY_TYPE.can_order;
    const useStatusFallback = !!styleCfg.use_status_fallback_colors;

    let finalBg = bgColor;
    let finalBorder = bgColor;
    let finalText = textColor;
    if (useStatusFallback) {
        if (type === 'unavailable') {
            finalBg = '#ffffff';
            finalBorder = '#ef4444';
            finalText = '#dc2626';
        } else if (type === 'can_order') {
            finalBg = '#f0fdf4';
            finalBorder = '#22c55e';
            finalText = '#15803d';
        }
    }

    const byType = type === 'unavailable'
        ? {
            card: styles.typeUnavailable,
            title: styles.typeUnavailableTitle,
            hint: styles.typeUnavailableHint
        }
        : (type === 'preorder'
            ? {
                card: styles.typePreorder,
                title: styles.typePreorderTitle,
                hint: styles.typePreorderHint
            }
            : {
                card: styles.typeCanOrder,
                title: styles.typeCanOrderTitle,
                hint: styles.typeCanOrderHint
            });

    const cardStyle = [
        styles.base,
        compact ? styles.compact : null,
        fullWidth ? styles.fullWidth : null,
        byType.card,
        {
            backgroundColor: finalBg,
            borderColor: finalBorder
        }
    ];

    return (
        <View style={[cardStyle, {flexDirection:'row', alignItems:'flex-start', borderWidth:useStatusFallback && type !== 'preorder' ? 1 : 0}]}>
            <Svg width={iconSize} height={iconSize} viewBox="0 0 24 24" style={{marginRight:6, flexShrink:0}} fill={finalText}>
                {type === 'unavailable' ? <><Circle cx="12" cy="12" r="10"/><Rect x="6" y="11" width="12" height="2.5" rx="1.2" fill="#fff"/></> :
                 type === 'preorder' ? <Path d="M7 2h2v2h6V2h2v2h2a2 2 0 0 1 2 2v12a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4V6a2 2 0 0 1 2-2h2V2Zm12 8H5v8a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-8ZM5 8h14V6H5v2Z"/> :
                 <Path d="M12 2a10 10 0 1 0 10 10A10.01 10.01 0 0 0 12 2Zm0 18a8 8 0 1 1 8-8a8.01 8.01 0 0 1-8 8Zm1-13h-2v6l5.2 3.2l1-1.65L13 12.05Z"/>}
            </Svg>
            <View style={{flexShrink:1}}>
                <Text style={{fontFamily:'open-regular', fontWeight:'400', fontSize:titleSize, lineHeight:titleSize*1.25, color:finalText}}>{badge.title}</Text>
                {badge.hint ? <Text style={{marginTop:1, fontFamily:'open-regular', fontSize:hintSize, lineHeight:hintSize*1.25, color:finalText}}>{badge.hint}</Text> : null}
            </View>
        </View>
    );
};

const styles = StyleSheet.create({
    base:{
        marginTop:6,
        marginBottom:4,
        paddingVertical:5,
        paddingHorizontal:8,
        borderRadius:8,
        borderWidth:1
    },
    typeUnavailable:{
        paddingVertical:6
    },
    typePreorder:{
        paddingVertical:6
    },
    typeCanOrder:{
        paddingVertical:5
    },
    compact:{
        paddingVertical:4,
        paddingHorizontal:7
    },
    fullWidth:{
        width:'90%',
        marginLeft:'5%'
    },
    headRow:{
        flexDirection:'row',
        alignItems:'center',
        justifyContent:'flex-start'
    },
    icon:{
        marginRight:6,
        textAlignVertical:'center',
        includeFontPadding:false
    },
    title:{
        fontSize:12,
        lineHeight:16,
        fontFamily:'open-bold, segoe ui, Arial',
        fontWeight:'700',
        textAlignVertical:'center',
        includeFontPadding:false,
        paddingTop:0,
        paddingBottom:0,
        textAlign:'left',
        flexShrink:1
    },
    typeUnavailableTitle:{
        letterSpacing:0
    },
    typePreorderTitle:{
        letterSpacing:0
    },
    typeCanOrderTitle:{
        letterSpacing:0
    },
    hint:{
        marginTop:2,
        fontSize:11,
        lineHeight:14,
        color:'#374151',
        paddingLeft:0,
        textAlign:'left'
    },
    typeUnavailableHint:{
        marginTop:2
    },
    typePreorderHint:{
        marginTop:3
    },
    typeCanOrderHint:{
        marginTop:2
    }
});
