import {useEffect} from 'react';
import {useDispatch, useSelector} from 'react-redux';
import {ServerDB} from '../serverDb';

// Обновляем доступность без замены категорий, корзины и состояния прокрутки.
export function MenuStopRefresh() {
    const cityId = useSelector(state => state.post.cityData?.cityId);
    const dispatch = useDispatch();
    useEffect(() => {
        if (!cityId) return;
        let closed = false, busy = false;
        const refresh = async () => {
            if (closed || busy || (typeof document !== 'undefined' && document.hidden)) return;
            busy = true;
            const startedAt = Date.now();
            try {
                const result = await ServerDB.getCatalogProducts(cityId);
                if (!closed && !result?.error && result?.list) {
                    dispatch({type:'MENU_STOP_REFRESH', cityId, catalog:result.list, startedAt});
                }
            } catch (_) {
                // Сохраняем последнюю доступность; окончательная проверка — на сервере.
            } finally { busy = false; }
        };
        const timer = setInterval(refresh, 60000);
        if (typeof document !== 'undefined') document.addEventListener('visibilitychange', refresh);
        return () => {
            closed = true;
            clearInterval(timer);
            if (typeof document !== 'undefined') document.removeEventListener('visibilitychange', refresh);
        };
    }, [cityId, dispatch]);
    return null;
}
