const MyTheme = {
    ...DefaultTheme,
    colors: {
        ...DefaultTheme.colors,
        background:"#ffffff"
    },
};
//
const navigatorOptions = {
    defaultNavigationOptions: {
        headerStyle: {
            backgroundColor: Platform.OS === 'android' ? '#fff' : '#fff',
            // height:0
        },
        headerTintColor: Platform.OS === 'android' ?  "#252622" : "#252622",
        headerForceInset: { top: Platform.OS === 'android' ? 'never' : 'always', bottom: 'never' },
    },
    gesturesEnabled: false,
    drawerLockMode: 'locked-closed',
};



//
//
const Drawer = createDrawerNavigator();
const styles = StyleSheet.create({
    i:{
        position:"absolute",
        top:0,
        right:-10,
        fontSize:10,
        paddingHorizontal:4,
        paddingVertical:2,
        backgroundColor:THEME.MAIN_COLOR,
        borderRadius:25,
        zIndex:1,
        minWidth:17,
        minHeight:10,
        display:"flex",
        justifyContent:"center",
        alignItems:"center",
        textAlign: "center",
        color:"#ffffff"
    }
});


const BaskerTabs = createDrawerNavigator();

function  BasketScreen({ navigation, route }){
    return (
        <BaskerTabs.Navigator initialRouteName="BasketScreen">
            <BaskerTabs.Screen name="BasketScreen" component={MainBakset}
                               options={({ route }) => ({
                                   headerTitle: route?.params?.title || "Корзина",
                                   headerLeft: () => (
                                       <HeaderButtons HeaderButtonComponent={AppHeaderIcon}>
                                           <Item
                                               title='Toggle Drawer'
                                               iconName='arrow-back'
                                               color={"#333333"}
                                               onPress={() => navigation.goBack()}
                                           />
                                       </HeaderButtons>
                                   ),
                                   drawerLockMode: 'locked-closed',
                                   headerShown: false
                               })}
            />
        </BaskerTabs.Navigator>
    )
}


const MultiScreen = createDrawerNavigator();

function ScreenMenu({navigation, route}) {
    return (
        <MultiScreen.Navigator>
            <MultiScreen.Screen name="Main" Label="Каталог" component={MainScreen} />
            <MultiScreen.Screen name="Product" component={ProductScreen}
                                options={({ route }) => ({
                                    title: route?.params?.title.split('&amp;quot;').join('"').split('&quot;').join('"') || "Заголовок",
                                    headerTitle: route?.params?.title.split('&amp;quot;').join('"').split('&quot;').join('"') || "Товар",
                                    headerLeft: () => (
                                        <HeaderButtons HeaderButtonComponent={AppHeaderIcon}>
                                            <Item
                                                title='Toggle Drawer'
                                                iconName='arrow-back'
                                                color={"#333333"}
                                                onPress={() => {
                                                    window.location.hash = 'Main';
                                                    navigation.navigate('Main')}
                                                }
                                            />
                                        </HeaderButtons>
                                    ),
                                    drawerLockMode: 'locked-closed',
                                    headerShown: true
                                })}
            />
        </MultiScreen.Navigator>
    );
}


// export const AppNavigation = createAppContainer(MainNavigator);
const Floating = createFloatingNavigator();

function HomeTabs() {
    return <Floating.Navigator initialRouteName="Catalog">
        <Floating.Screen name="Catalog" component={ScreenMenu}/>
        <Floating.Screen name="Basket" component={BasketScreen}/>
        <Floating.Screen name="InfoDelivery" component={InfoDeliveryScreen}/>
        <Floating.Screen name="SalesInfo" component={SalesInfoScreen}/>
        <Floating.Screen name="ProfileScreen" component={ProfileScreen}/>
    </Floating.Navigator>;
}

