import React, {useEffect, useMemo, useState} from 'react';
import {Modal, View, Text, StyleSheet, ScrollView, Pressable, ActivityIndicator} from 'react-native';
import {THEME} from '../../theme';
import {ServerDB} from '../../serverDb';
import {getMenuStopAvailability, isTimeInAnyWindow, hasPreorderRestrictions} from '../../utils/menuStop';
import {AntDesign} from '../../components/SystemIcons';
import {usePickupAvailability, isPickupSlotOpen} from '../../utils/pickupAvailability';

const EMPTY_PRODUCTS = [];

export const PreorderPickerModal = ({visible, onClose, onConfirm, product, cityId, extraProducts = EMPTY_PRODUCTS}) => {
    const {isPickup, point: pickupPoint} = usePickupAvailability();
    const [error, setError] = useState('');
    const texts = product?.menu_stop_availability?.ui_texts || {};
    const [loading, setLoading] = useState(false);
    const [dateList, setDateList] = useState([]);
    const [dateSelected, setDateSelected] = useState('');
    const [timeList, setTimeList] = useState([]);
    const [timeSelected, setTimeSelected] = useState('');
    const [rawDateMap, setRawDateMap] = useState({});

    const productsForCheck = useMemo(() => {
        const src = [];
        if (product && typeof product === 'object') { src.push(product); }
        if (Array.isArray(extraProducts)) {
            extraProducts.forEach((p) => {
                if (p && typeof p === 'object') { src.push(p); }
            });
        }
        return src;
    }, [product, extraProducts]);
    const availabilities = useMemo(() => {
        // Всегда учитываем добавляемый товар (product),
        // а extraProducts только дополняют пересечение (товары корзины).
        return productsForCheck
            .map((p) => getMenuStopAvailability(p))
            .filter(hasPreorderRestrictions);
    }, [productsForCheck]);

    const normalizeTime = (val) => {
        const raw = String(val || '').trim();
        const m = /^(\d{2}):(\d{2})/.exec(raw);
        if (!m) { return raw; }
        return `${m[1]}:${m[2]}`;
    };

    const reloadDates = async () => {
        if (!visible) { return; }
        setLoading(true);
        setError('');
        setTimeSelected('');
        try{
            const raw = await ServerDB.getDateList(cityId);
            setRawDateMap(raw || {});
            let dates = Object.keys(raw || {});
            dates = dates.filter(date => {
                const day = raw[date];
                const stoppedProducts = (day?.productStop || []).map(String);
                const stoppedCategories = (day?.categoryStop || []).map(String);
                return productsForCheck.every(p =>
                    !stoppedProducts.includes(String(p.id)) &&
                    !stoppedCategories.includes(String(p.id_Category))
                );
            });
            if (availabilities.length > 0) {
                const dateSetList = availabilities.map((a) => {
                    const set = {};
                    (a.preorder_next_dates || []).forEach((o) => {
                        if (o?.date) { set[o.date] = true; }
                    });
                    return set;
                });
                dates = dates.filter((d) => dateSetList.every((set) => !!set[d]));
            }
            setDateList(dates);
            const firstDate = dates[0] || '';
            setDateSelected(firstDate);
            setTimeSelected('');
            if (firstDate) {
                fillTimes(firstDate, raw || {});
            } else {
                setTimeList([]);
            }
        } catch (error) {
            setDateList([]);
            setDateSelected('');
            setTimeList([]);
            setError('Не удалось загрузить доступное время. Попробуйте ещё раз.');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (visible) {
            reloadDates();
        }
    }, [visible, cityId, product, extraProducts, isPickup, pickupPoint]);

    const fillTimes = (dateValue, sourceRaw = rawDateMap) => {
        const windowsByAvailability = availabilities.map((a) => {
            const dayOffer = (a.preorder_next_dates || []).find((o) => o && o.date === dateValue);
            return Array.isArray(dayOffer?.windows) ? dayOffer.windows : [];
        });
        const timeRaw = sourceRaw?.[dateValue]?.timeList || {};
        const times = Object.keys(timeRaw).map((key) => {
            const row = timeRaw[key];
            const normalizedKey = normalizeTime(key);
            const normalizedTitle = normalizeTime((row && row.title) ? row.title : key);
            const byDateList = !!row && row['false'] === false;
            const byWindows = windowsByAvailability.length === 0
                ? true
                : windowsByAvailability.every((wins) => isTimeInAnyWindow(normalizedKey, wins) || isTimeInAnyWindow(normalizedTitle, wins));
            const disabled = !(byDateList && byWindows)
                || (isPickup && !isPickupSlotOpen(pickupPoint, dateValue, normalizedKey));
            return { key: normalizedKey, title: normalizedTitle || normalizedKey, disabled };
        });
        setTimeList(times);
    };

    const handleConfirm = () => {
        const safeDate = String(dateSelected || '').trim();
        const safeTime = String(timeSelected || '').trim();
        if (loading || !dateList.includes(safeDate) || !timeList.some(t => t.key === safeTime && !t.disabled)) {
            return;
        }
        if (onConfirm) {
            onConfirm({ dateDelivery: safeDate, timeDelivery: safeTime });
        }
    };

    const onSelectDate = (dateValue) => {
        setDateSelected(dateValue);
        setTimeSelected('');
        fillTimes(dateValue);
    };

    const dateRu = (d) => {
        if (!d || d.indexOf('-') < 0) { return d; }
        const p = d.split('-');
        const months = {
            '01': 'января',
            '02': 'февраля',
            '03': 'марта',
            '04': 'апреля',
            '05': 'мая',
            '06': 'июня',
            '07': 'июля',
            '08': 'августа',
            '09': 'сентября',
            '10': 'октября',
            '11': 'ноября',
            '12': 'декабря'
        };
        const day = parseInt(p[2], 10);
        const month = months[p[1]] || p[1];
        return `${day} ${month}`;
    };

    if (!visible) return null;

    return (
        <Modal transparent visible={!!visible} animationType="fade" onRequestClose={onClose}>
            <View style={styles.overlay}>
                <View style={styles.card}>
                    <Text style={styles.title}>{texts.modal_preorder_title || 'Товар доступен только по предзаказу'}</Text>
                    <Text style={styles.sub}>{texts.modal_preorder_text || 'Выберите дату и время, чтобы продолжить оформление.'}</Text>
                    {loading ? <ActivityIndicator color={THEME.MAIN_COLOR} style={{marginVertical: 14}}/> : null}
                    {error ? <Pressable onPress={reloadDates}><Text style={{color:THEME.DANGER_COLOR, paddingVertical:10}}>{error} Повторить</Text></Pressable> : null}

                    {!loading ? (
                        <View style={styles.contentRow}>
                            <View style={styles.colLeft}>
                                <View style={styles.colHead}>
                                    <AntDesign name="calendar" size={14} color={THEME.MAIN_COLOR}/>
                                    <Text style={styles.colHeadText}>{texts.modal_preorder_date_label || 'Дата'}</Text>
                                </View>
                                <ScrollView style={styles.listLeft}>
                                    {dateList.length ? dateList.map((d) => (
                                        <Pressable key={`d_${d}`} style={[styles.optionDate, dateSelected === d ? styles.optionDateActive : null]} onPress={() => onSelectDate(d)}>
                                            <Text style={[styles.optionDateText, dateSelected === d ? styles.optionDateTextActive : null]}>{dateRu(d)}</Text>
                                        </Pressable>
                                    )) : <Text style={styles.empty}>Нет дат</Text>}
                                </ScrollView>
                            </View>
                            <View style={styles.colDivider}/>
                            <View style={styles.colRight}>
                                <View style={styles.colHead}>
                                    <AntDesign name="clockcircleo" size={14} color={THEME.MAIN_COLOR}/>
                                    <Text style={styles.colHeadText}>{texts.modal_preorder_time_label || 'Время'}</Text>
                                </View>
                                <ScrollView style={styles.listRight}>
                                    <View style={styles.timeGrid}>
                                        {timeList.length ? timeList.map((t) => (
                                            <Pressable
                                                key={`t_${t.key}`}
                                                disabled={t.disabled}
                                                style={[
                                                    styles.optionTime,
                                                    timeSelected === t.key ? styles.optionTimeActive : null,
                                                    t.disabled ? styles.optionTimeDisabled : null
                                                ]}
                                                onPress={() => setTimeSelected(t.key)}
                                            >
                                                <Text style={[
                                                    styles.optionTimeText,
                                                    timeSelected === t.key ? styles.optionTimeTextActive : null,
                                                    t.disabled ? styles.optionTimeTextDisabled : null
                                                ]}>{t.title}</Text>
                                            </Pressable>
                                        )) : <Text style={styles.empty}>Нет времени</Text>}
                                    </View>
                                </ScrollView>
                            </View>
                        </View>
                    ) : null}

                    <View style={styles.pickedBox}>
                        <AntDesign name="calendar" size={14} color={THEME.MAIN_COLOR}/>
                        <Text style={styles.pickedLabel}>Выбрано:</Text>
                        <Text style={styles.pickedValue}>{dateSelected && timeSelected ? `${dateRu(dateSelected)}, ${timeSelected}` : 'не выбрано'}</Text>
                    </View>

                    <View style={styles.actions}>
                        <Pressable style={[styles.btn, styles.btnGhost]} onPress={onClose}>
                            <Text style={styles.btnGhostText}>{texts.modal_preorder_cancel || 'Отмена'}</Text>
                        </Pressable>
                        <Pressable
                            hitSlop={10}
                            disabled={loading || !dateSelected || !timeSelected || !!error}
                            style={[styles.btn, styles.btnMain, (!dateSelected || !timeSelected) ? styles.btnMainDisabled : null]}
                            onPress={handleConfirm}
                        >
                            <Text style={styles.btnMainText}>{texts.modal_preorder_apply || 'Выбрать'}</Text>
                        </Pressable>
                    </View>
                </View>
            </View>
        </Modal>
    );
};

