import {PromokodeClass} from '../../PromokodeClass';
import {NumberFormatPrice} from '../../templateComponents/NumberFormat/NumberFormat';
import {CheckModifyProductAccordance} from '../CheckModifyFunction/CheckModifyProductAccordance';
import {getTypeDiscountPromoInfo} from '../SystemFunction/getTypeDiscountPromoInfo';
// Общая подготовка цен без dispatch и изменения исходной Redux-корзины.
export const getBasketPromoNeedCount = (basket, PromoData) => {
        if (!Array.isArray(basket)) {
            return 0;
        }

        let count = 0;
        basket.forEach((item) => {
            (item?.type || []).forEach((d) => {
                const categoryCondition = (PromoData?.dop_settings?.id_category_settings) * 1 === (d?.categoryId) * 1;
                const productCondition = (PromoData?.dop_settings?.id_product_default) * 1 === (item?.id) * 1;
                const typeName = ({0: "price", 1: "small", 2: "sred", 3: "big"})[(d?.type_id) * 1] || "unknown";
                const typeCondition =
                    PromoData?.dop_settings?.type_product_default === typeName ||
                    PromoData?.dop_settings?.type_product_default === "all";

                if (
                    (categoryCondition && PromoData?.dop_settings?.id_category_settings !== 0 && PromoData?.dop_settings?.id_product_default === 0 && PromoData?.dop_settings?.type_product_default === "all") ||
                    (categoryCondition && PromoData?.dop_settings?.id_category_settings !== 0 && PromoData?.dop_settings?.id_product_default === 0 && typeCondition) ||
                    (productCondition && PromoData?.dop_settings?.type_product_default === "all") ||
                    (categoryCondition && typeCondition && PromoData?.dop_settings?.id_product_default === 0) ||
                    (productCondition && typeCondition) ||
                    (PromoData?.dop_settings?.id_category_settings === 0 && PromoData?.dop_settings?.id_product_default === 0 && PromoData?.dop_settings?.type_product_default !== "all" && typeCondition)
                ) {
                    count += (d?.count || 0) * 1;
                }
            });
        });
        return count;

};
export const prepareBasketPricing = ({basket: sourceBasket, allProducts, PromoData, PromokodeActiveStatus,
    PromokodeErrorInfo, ThreeForTwoListProduct, BDayActive, needCount, SumReturnsTopping = 0}, def = true) => {
    const basket = (sourceBasket || []).map(item => ({
        ...item,
        type: (item.type || []).filter(type => Array.isArray(allProducts?.[type.categoryId]?.ProductList?.[item.id])
            && allProducts[type.categoryId].ProductList[item.id].some(product => product.type_product === type.type_id))
    })).filter(item => item.type.length > 0);
    let countProductListBasket = 0;

    const handleSetProductArrayPromokode = (Product,type_price,countProductBasket,countAllProductInCart,sumRemaining,Type_Product,idProduct, return_default = true , modifyList = [],BDay=BDayActive)=>{

        return PromokodeClass.getPriceFromPromokode(Product,0, type_price,countProductBasket,countAllProductInCart,sumRemaining,Type_Product,PromoData,countProductListBasket,idProduct,return_default,modifyList,0,BDay,needCount);
    };

    const getTypeProductData = (type_id,ProductDataAll) =>{
        let Returns = {};

        ProductDataAll.forEach((type,number)=>{
            if(type_id === type.type_product){
                Returns = type;
            }
        });

        return Returns;
    };

    const getProductNoDiscount = (ProductData,count,sumModifyPrice = 0,modifyListBasket=[])=>{
        let statusFree = false;

        let ReturnArray = {
                sumPriceDefOneProduct:0, //Сумма 1 товара без скидки,
                SumProductNoDiscount:0, // Сумма товаров без скидки
                countProductNoDiscount:0, //кол-во товаров без сидки
        };

        let DataProductThreeForTwo = getListThreeForTwo(ProductData,count,modifyListBasket);

        statusFree = DataProductThreeForTwo.status;
        if(statusFree === true) {
            count -= DataProductThreeForTwo.count;
        }

        if(ProductData.price_discount === false){
            ReturnArray = {
                sumPriceDefOneProduct: (ProductData.price*1)+sumModifyPrice, //Сумма 1 товара без скидки,
                SumProductNoDiscount: ((ProductData.price*1)+sumModifyPrice)*(count*1), // Сумма товаров без скидки
                countProductNoDiscount:count, //кол-во товаров без сидки
                titleHelper:"Товары которые идут без скидок совсем"
            }
        }
        return ReturnArray;
    };

    const getProductDiscount = (ProductData,count, sumModifyPrice = 0,modifyListBasket=[])=>{
        let statusFree = false;
        let ReturnArray = {
            countProductDiscountBasket:0, // кол-во товаров по скидке
            sumProductDiscount:0,
            sumPriceDefOneProduct:0, //Сумма 1 товара без скидки,
        }

        let DataProductThreeForTwo = getListThreeForTwo(ProductData,count,modifyListBasket);

        statusFree = DataProductThreeForTwo.status;
        if(statusFree === true) {
            count -= DataProductThreeForTwo.count;
        }

        if(ProductData.price_discount !== false){
    const oldPrice = (ProductData?.price_discount?.old_price*1) + sumModifyPrice;
    const newPrice = (ProductData?.price_discount?.new_price*1) + sumModifyPrice;

            ReturnArray = {
                sumPriceDefOneProduct: newPrice, //Сумма 1 товар по акционной цене,
                SumProductNoDiscount: oldPrice*(count*1), // Сумма товаров без скидки
                priceProductNoDiscount: oldPrice, //Цена 1 товара без скидки
                SumProductDiscount: newPrice*(count*1), // Сумма товаров без скидки
                countProductDiscountBasket:count, //кол-во товаров со сидкой

                discountOneProduct:oldPrice-(newPrice),
                discountAllProduct:(oldPrice-newPrice)*(count*1),

                titleHelper:"Товары которые идут со скидкой по умолчанию в каталоге",

                discountOneProductFromBase: oldPrice,

                discountOneProductFromSale: newPrice
            };
        }
        return ReturnArray;

    };

    const getListThreeForTwo = (ProductData,count,modifyListBasket=[])=>{
        let statusFree = false;
        let countProductInFree = 0;
        if(PromokodeActiveStatus === true && PromoData?.promokodeInfo?.addition_discount === false){
            return {"status":statusFree,"countProductInFree":countProductInFree,"count":count};
        }
        ThreeForTwoListProduct.forEach((data,number)=>{
            if(data.idProduct == ProductData.id_Product){
                if(data.type_id == ProductData.type_product){
                    if(CheckModifyProductAccordance(data?.modifyList,modifyListBasket)){
                        statusFree = true;
                        countProductInFree++;
                    }
                }
            }
        });

        if(count>countProductInFree){
            count = countProductInFree;
        }

        return {"status":statusFree,"countProductInFree":countProductInFree,"count":count};
    };

    const getProductThreeForTwo = (ProductData,count,sumModifyPrice = 0,modifyListBasket=[])=>{
        let statusFree = false;
        let countProductInFree = 0;

        let DataProductThreeForTwo = getListThreeForTwo(ProductData,count,modifyListBasket);

        count = DataProductThreeForTwo.count;
        statusFree = DataProductThreeForTwo.status;

        let ReturnArray = {
            priceOneProductDiscount: 0, //Цена 1 товара со скидкой,
            SumProductNoDiscount: 0, // Сумма товаров без скидки
            priceProductNoDiscount: 0, //Цена 1 товара без скидки
            SumProductDiscount: 0, // Сумма всех товаров со скидкой
            countProductDiscountBasket:0, //кол-во товаров со сидкой
            discountOneProduct:0,
            discountAllProduct:0,
            titleHelper:"Товары которые идут по акции 3 = 2"
        }

        if(statusFree === true){
            if(ProductData.price_discount !== false) {
                ReturnArray = {
                    priceOneProductDiscount: 0, //Цена 1 товара со скидкой,
                    sumAllProductNoDiscount: ((ProductData?.price_discount?.old_price * 1)+sumModifyPrice) * (count * 1), // Сумма всех товаров без скидки
                    priceOneProductNoDiscount: ((ProductData?.price_discount?.old_price * 1)+sumModifyPrice), //Цена 1 товара без скидки
                    sumAllProductDiscount: 0, // Сумма всех товаров со скидкой
                    countAllProductDiscountBasket: count, //кол-во товаров со сидкой
                    discountOneProduct: ((ProductData?.price_discount?.old_price * 1)+sumModifyPrice), //скидка за 1 товар
                    discountAllProduct: (((ProductData?.price_discount?.old_price * 1)+sumModifyPrice) * (count * 1)), // скидка за все товары
                    titleHelper: "Товары которые идут по акции 3 = 2"
                }
            }else{
                ReturnArray = {
                    priceOneProductDiscount: 0, //Цена 1 товара со скидкой,
                    sumAllProductNoDiscount: ((ProductData.price * 1)+sumModifyPrice) * (count * 1), // Сумма всех товаров без скидки
                    priceOneProductNoDiscount: ((ProductData.price * 1)+sumModifyPrice), //Цена 1 товара без скидки
                    sumAllProductDiscount: 0, // Сумма всех товаров со скидкой
                    countAllProductDiscountBasket: count, //кол-во товаров со сидкой
                    discountOneProduct: ((ProductData.price * 1)+sumModifyPrice), //скидка за 1 товар
                    discountAllProduct: (((ProductData.price * 1)+sumModifyPrice) * (count * 1)), // скидка за все товары
                    titleHelper: "Товары которые идут по акции 3 = 2"
                }
            }
        }
        return ReturnArray;
    };

    const checkedFreeProductThreeForTwo = (product)=>{
        let statusFree = false;
        let countProductInFree = 0;
        if(PromokodeActiveStatus === true && PromoData?.promokodeInfo?.addition_discount === false){
            return {"status":statusFree,"countProductInFree":countProductInFree};
        }
        ThreeForTwoListProduct.forEach((data,number)=>{
            if(data.idProduct == product.id_Product){
                if(data.type_id == product.type_product){
                    statusFree = true;
                    countProductInFree++;
                }
            }
        });

        return {"status":statusFree,"countProductInFree":countProductInFree};
    }

    const getBasketPromokodeActive = (def = true)=>{
        let ReturnBasketArray = [];
        let AllDiscount = 0;
        let AllPrice = 0;
        let AllPriceDiscounts = 0;
        let  AllPriceDIscountCheck = 0;

        let ProductListForPromokode = [];
        let countAllProductInCart = 0;

        let sumRemaining = 0;

        let NewBasketView = [];

        basket.sort( (prev, next)=>{

            let nextSum = getTypeProductData(next.type[0].type_id,allProducts[next.type[0].categoryId].ProductList[next.id]).price;

            let PrevSum = getTypeProductData(prev.type[0].type_id,allProducts[prev.type[0].categoryId].ProductList[prev.id]).price;

            return nextSum - PrevSum;
        });

        basket.forEach((item, number)=>{
            let countFreeProductThreeForTwo = 0;
            item.type.forEach((type, n)=>{
                let TypeProductData = getTypeProductData(type.type_id,allProducts[type.categoryId].ProductList[item.id],type?.modifyList);

                let statusInFreeProductThreeForTwo = checkedFreeProductThreeForTwo(TypeProductData);
                countFreeProductThreeForTwo = statusInFreeProductThreeForTwo.countProductInFree;
                let countInPromochek = type.count;
                if(statusInFreeProductThreeForTwo.status === true){
                    countInPromochek = type.count-countFreeProductThreeForTwo;
                }

                let ReturnResult = handleSetProductArrayPromokode(TypeProductData,TypeProductData.price,countInPromochek,countAllProductInCart,sumRemaining,type.type_id,item.id,def,type?.modifyList);
                countProductListBasket = ReturnResult.countProductinCartLocal;
                countAllProductInCart = ReturnResult.countAllProductInCart;
                sumRemaining = ReturnResult.sumRemaining;

                if(ReturnResult.conditionProductPromokode.status == true){
                    ReturnResult.conditionProductPromokode = {...ReturnResult.conditionProductPromokode,...{count:countProductListBasket}}
                    ProductListForPromokode.push(ReturnResult.conditionProductPromokode);
                }

                let sumModifyPrice = 0;

                type?.modifyList?.forEach((d,n)=>{
                    sumModifyPrice += d.price*1;
                });

                let PriceDef = ((TypeProductData.price*1)+(sumModifyPrice*1))*countInPromochek;
                let PriceDefDiscounts = ((TypeProductData.price*1)+(sumModifyPrice*1))*countInPromochek;

                if(PromoData?.promokodeInfo?.promo_total === true && PromokodeErrorInfo.showIconError === false) {
                    let PriceProductsII = (TypeProductData.price*1);
                    if(typeof (TypeProductData.price_discount) === "object"){
                        PriceProductsII = TypeProductData?.price_discount?.new_price*1;
                    }
                    PriceDefDiscounts = (PriceProductsII+(sumModifyPrice*1))*countInPromochek;
                }

                let modifyListProduct = [];

                if(type?.modifyList?.length > 0){
                    modifyListProduct = type?.modifyList;
                }else{
                    modifyListProduct = [];
                }

                let PriceDefOneProductNoDiscount = ((TypeProductData.price*1)+(sumModifyPrice*1));
                let countProductNoDiscount = (type.count-countProductListBasket); //Кол-во товаров без скидки
                let SumProductNoDiscount = countProductNoDiscount*PriceDefOneProductNoDiscount; //Сумма продута без учета скидочных товаров

                let TpmInfoProductSale = [];

                   let ProductListNoDiscount  = getProductNoDiscount(TypeProductData,countProductNoDiscount,sumModifyPrice,modifyListProduct);

                let ProductListDiscount = getProductDiscount(TypeProductData,countProductNoDiscount,sumModifyPrice,modifyListProduct);

                let ProductListPromokodeDiscount = {
                        countProductDiscountBasket:countProductListBasket, // кол-во товаров по скидке
                        sumProductDiscount:NumberFormatPrice(ReturnResult.sumProductDiscount,0,'.',''), //сумма товаров со скидкой
                        priceProductDiscount:NumberFormatPrice(ReturnResult.sumProductDiscount,0,'.','')/countProductListBasket || 0, //цена товара со скидкой
                        sumPriceDefOneProduct:NumberFormatPrice(PriceDefOneProductNoDiscount,0,'.',''), //Сумма 1 товара без скидки,
                        sumPriceAllProductNoDiscount:NumberFormatPrice(PriceDefOneProductNoDiscount,0,'.','')*countProductListBasket, //Сумма всех товаров без скидки,
                        discountOneProduct: NumberFormatPrice(PriceDefOneProductNoDiscount-(NumberFormatPrice(ReturnResult.sumProductDiscount,0,'','')/countProductListBasket),0,'.',''),// сумма скидки за 1 товар
                        discountAllProduct: NumberFormatPrice((countProductListBasket*(PriceDefOneProductNoDiscount-(NumberFormatPrice(ReturnResult.sumProductDiscount,0,'','')/countProductListBasket))),0,'.',''),// сумма скидки за все товары
                        discountOneProductFromBase: ProductListDiscount.discountOneProductFromBase,
                        discountOneProductFromSale: ProductListDiscount.discountOneProductFromSale,

                        titleHelper:"Товары которые идут со скидкой по промокоду",
                       sumProductDiscountFIrstPricePromo:ProductListDiscount?.sumPriceDefOneProduct*1 || 0,
                       sumAllProductDiscountFIrstPricePromo:ProductListDiscount?.sumPriceDefOneProduct*1*countProductListBasket || 0
                    };

                let PriceDefMinusDiscount = PriceDef/type.count - (ProductListDiscount?.sumPriceDefOneProduct*1*countProductListBasket);

                if(ProductListDiscount?.sumPriceDefOneProduct*1>0 && countProductListBasket>0) {
                    AllPriceDIscountCheck = AllPrice + (PriceDef - PriceDefMinusDiscount);
                }else{
                    AllPriceDIscountCheck = AllPrice + (PriceDef);
                }

                AllPrice = AllPrice+(PriceDef);

                if(PromoData?.promokodeInfo?.promo_total === true && PromoData?.promokodeInfo?.addition_discount === false){
                    if(TypeProductData?.price_discount?.old_price*1 !== TypeProductData?.price_discount?.new_price*1 && TypeProductData?.price_discount !== false){
                    }else {
                        AllPriceDiscounts += PriceDefDiscounts
                    }
                }
                else
                { AllPriceDiscounts += PriceDefDiscounts;}

                let PriceDiscount = PriceDef-ReturnResult.SumResult;
                PriceDiscount <0 ? PriceDiscount =0 : PriceDiscount = PriceDiscount;
                AllDiscount = AllDiscount+PriceDiscount;

                    let ProductListThreeForTwo = getProductThreeForTwo(TypeProductData,countProductNoDiscount,sumModifyPrice,modifyListProduct);

                let ArrayPush = {
                    id_product:item.id,
                    type_product:type.type_id,
                    sumDiscount:PriceDiscount, //Сумма скидки по всем товарам
                    sumPriceDef:PriceDef, //Сумма всех товаров без скидки
                    sumPriceSale:ReturnResult.SumResult, //Стоимость товара с учетом скидки
                    count:type.count,
                    modifyListProduct:modifyListProduct,
                    tmpData:{
                        ProductListNoDiscount,
                        ProductListPromokodeDiscount,
                        ProductListDiscount,
                        ProductListThreeForTwo
                    }
                };

                ReturnBasketArray.push(ArrayPush);
            });
        });

        if(PromoData !== null){

            if(PromoData.dop_settings.type_summa_check === '0'){

                let SummaCheckMinPrice = AllPriceDIscountCheck;
                ReturnBasketArray.forEach((d,n)=>{
                    const promoCount = d.tmpData?.ProductListPromokodeDiscount?.countProductDiscountBasket ?? 0;
                    if (promoCount <= 0) {
                        return;
                    }

                    const saleUnit = (d.tmpData?.ProductListDiscount?.sumPriceDefOneProduct || 0) * 1;
                    const normalUnit = (d.tmpData?.ProductListNoDiscount?.sumPriceDefOneProduct || 0) * 1;
                    const promoBaseUnit = (d.tmpData?.ProductListPromokodeDiscount?.sumPriceDefOneProduct || 0) * 1;

                    let unitPrice = 0;
                    if (saleUnit > 0) {
                        unitPrice = saleUnit;
                    } else if (normalUnit > 0) {
                        unitPrice = normalUnit;
                    } else if (promoBaseUnit > 0) {
                        unitPrice = promoBaseUnit;
                    }

                    if (unitPrice <= 0) {
                        return;
                    }

                    SummaCheckMinPrice -= unitPrice * promoCount;
                });

                if(SummaCheckMinPrice<PromoData.dop_settings.summa_min_active){

                    let NewRetunrDataBasket = [];

                    ReturnBasketArray.forEach((d,n)=>{
                        d.tmpData.ProductListPromokodeDiscount.sumProductDiscount = d.tmpData.ProductListPromokodeDiscount.sumPriceAllProductNoDiscount;
                        AllDiscount = 0;
                    });

                }
            }

            if(PromoData.dop_settings.type_summa_check === '1'){

                let SummaCheckMinPrice = AllPriceDIscountCheck;

                ReturnBasketArray.forEach((d,n)=>{
                    const promoCount = d.tmpData?.ProductListPromokodeDiscount?.countProductDiscountBasket ?? 0;
                    if (promoCount <= 0) {
                        return;
                    }

                    const saleUnit = (d.tmpData?.ProductListDiscount?.sumPriceDefOneProduct || 0) * 1;
                    const normalUnit = (d.tmpData?.ProductListNoDiscount?.sumPriceDefOneProduct || 0) * 1;
                    const promoBaseUnit = (d.tmpData?.ProductListPromokodeDiscount?.sumPriceDefOneProduct || 0) * 1;
                    const promoPriceUnit = (d.tmpData?.ProductListPromokodeDiscount?.priceProductDiscount || 0) * 1;

                    let unitPrice = 0;
                    if (saleUnit > 0) {
                        unitPrice = saleUnit;
                    } else if (normalUnit > 0) {
                        unitPrice = normalUnit;
                    } else if (promoBaseUnit > 0) {
                        unitPrice = promoBaseUnit;
                    }

                    if (unitPrice <= 0) {
                        return;
                    }

                    const discountOne = unitPrice > promoPriceUnit ? (unitPrice - promoPriceUnit) : 0;
                    if (discountOne <= 0) {
                        return;
                    }
                    SummaCheckMinPrice -= discountOne * promoCount;
                });

                if(SummaCheckMinPrice<PromoData.dop_settings.summa_min_active){
                    let NewRetunrDataBasket = [];

                    ReturnBasketArray.forEach((d,n)=>{
                        d.tmpData.ProductListPromokodeDiscount.sumProductDiscount = d.tmpData.ProductListPromokodeDiscount.sumPriceAllProductNoDiscount;
                        AllDiscount = 0;
                    });

                }
            }

            if(PromoData.dop_settings.type_summa_check === '2'){

                let SummaCheckMinPrice = AllPriceDIscountCheck;

                if(SummaCheckMinPrice<PromoData.dop_settings.summa_min_active){
                    let NewRetunrDataBasket = [];

                    ReturnBasketArray.forEach((d,n)=>{
                        d.tmpData.ProductListPromokodeDiscount.sumProductDiscount = d.tmpData.ProductListPromokodeDiscount.sumPriceAllProductNoDiscount;
                        AllDiscount = 0;
                    });
                }
            }

        }

        let totalPromoDiscount = 0;
        let DispatchData = {
            allSumDiscount:AllDiscount,
            arrayProductDiscount:ReturnBasketArray,
            sumPreorderToppting:SumReturnsTopping,
            listProductInCartForPromokode:ProductListForPromokode,
            totalPromoDiscount: totalPromoDiscount
        };

        if(PromoData?.promokodeInfo?.promo_total === true && PromokodeErrorInfo.showIconError === false) {
            totalPromoDiscount = getTypeDiscountPromoInfo(PromoData.promokodeInfo.sale_type, PromoData.promokodeInfo.sale, AllPriceDiscounts);
            DispatchData.totalPromoDiscount = totalPromoDiscount;
            DispatchData.allSumDiscount = totalPromoDiscount;
        }else{
        }

        return DispatchData;
    };
    return getBasketPromokodeActive(def);

};
